import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.4.17 — Delete Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/03-agency-workspace/3-4-17-delete-workspace/spec.md","filePath":"feature/srs/03-agency-workspace/3-4-17-delete-workspace/spec.md"}'),s={name:"feature/srs/03-agency-workspace/3-4-17-delete-workspace/spec.md"};function c(n,e,d,i,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-4-17-—-delete-workspace" tabindex="-1">FR 3.4.17 — Delete Workspace <a class="header-anchor" href="#fr-3-4-17-—-delete-workspace" aria-label="Permalink to &quot;FR 3.4.17 — Delete Workspace&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.4.17</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-030</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Delete Workspace</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Agency &amp; Workspace (<code>FR 3.4</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-16</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-scope" tabindex="-1">1. Objective &amp; Scope <a class="header-anchor" href="#_1-objective-scope" aria-label="Permalink to &quot;1. Objective &amp; Scope&quot;">​</a></h2><p>Xóa mềm Workspace (/workspaces/:id/settings). Chỉ duy nhất Owner mới có quyền xóa Workspace. Khi xóa, toàn bộ dữ liệu bên trong chuyển sang trạng thái INACTIVE, các thành viên không còn quyền truy cập, nhưng dữ liệu được bảo lưu và Owner có thể khôi phục lại hoàn toàn trong vòng 30 ngày (BR-16).</p><p><strong>Implementation Summary:</strong> Strictly enforces parent Agency <code>Owner</code> authorization (<code>agency.ownerId == currentUser.id</code>), requires exact Workspace-name confirmation in <code>WorkspaceDangerZone.tsx</code>, soft-deletes the Workspace (<code>EntityStatus.SOFT_DELETED</code>, <code>deletedAt = now()</code>), hides it from active listings, and supports 30-day restoration (<code>WORKSPACE_RESTORE_WINDOW_DAYS = 30</code>, <code>BR-16</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner</code>), I want to execute <strong>Delete Workspace</strong> with strict multi-tenant authorization and real-time state consistency, so that organizational governance and role-scoped workflows satisfy <code>BR-16</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Gate:</strong> Only authenticated users holding <code>Owner</code> within the target Agency/Workspace scope may invoke <code>DELETE /api/v1/workspaces/{workspaceId} · POST /api/v1/workspaces/{workspaceId}/restore</code>; unauthorized callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Business Rule Enforcement (<code>BR-16</code>):</strong> Backend service logic (<code>WorkspaceServiceImpl.deleteWorkspace() / restoreWorkspace()</code>) enforces all domain invariants, uniqueness constraints, and soft-delete / single-Manager / TTL rules before committing state changes.</li><li><strong>Standardized Envelope &amp; Persistence:</strong> Reads and mutations against PostgreSQL <code>workspaces</code> (<code>status = SOFT_DELETED</code>, <code>deleted_at</code>), <code>agencies</code>, <code>audit_logs</code> return <code>ApiResponse&lt;T&gt;</code> with deterministic <code>ErrorCode</code> mappings (<code>403 FORBIDDEN</code> (<code>BR-15</code>), <code>404 WORKSPACE_NOT_FOUND</code>, <code>400 WORKSPACE_NOT_DELETED</code>, <code>410 RESTORE_WINDOW_EXPIRED</code> (<code>BR-16</code>)) and <code>X-Request-Id</code> correlation.</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> All UI labels, empty states, dialogs, and toast notifications use parallel locale keys (<code>workspace.dangerZone.* / workspace.delete.*</code>) in <code>vi</code> and <code>en</code> bundles — zero hardcoded strings in JSX/TSX.</li><li><strong>Semantic Light/Dark Theme:</strong> All cards, tables, badges, drawers, and confirmation modals use semantic CSS variables / Tailwind <code>dark:</code> tokens (<code>brandhub-web</code>) and <code>useTheme()</code> tokens (<code>brandhub-mobile-app</code>) with WCAG-compliant contrast.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/workspace/detail.tsx</code>, <code>src/pages/workspace/components/settings/WorkspaceDangerZone.tsx</code>, <code>src/pages/workspace/hooks/useClearStoragePreview.ts</code>, <code>src/pages/workspace/services/workspaceService.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/settings/WorkspaceSettingsScreen.tsx</code>, <code>src/services/workspaceService.ts</code></li><li><strong>Interactive States:</strong><ul><li><strong>Loading:</strong> Skeleton cards/rows and disabled in-flight submit buttons preventing duplicate requests.</li><li><strong>Empty State:</strong> Contextual empty state with localized guidance and primary CTA where permitted by role.</li><li><strong>Success:</strong> TanStack Query cache invalidation + localized confirmation toast without full-page reload.</li><li><strong>Error / Recovery:</strong> Inline field validation or retryable <code>DataErrorState</code> banner mapped from backend <code>ErrorCode</code> — never silently falling back to mock data.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><ul><li><strong>Endpoints:</strong> <code>DELETE /api/v1/workspaces/{workspaceId} · POST /api/v1/workspaces/{workspaceId}/restore</code></li><li><strong>Controller &amp; Service (<code>brandhub-business-service</code>):</strong> <code>WorkspaceController.deleteWorkspace() / restoreWorkspace()</code> -&gt; <code>WorkspaceServiceImpl.deleteWorkspace() / restoreWorkspace()</code></li><li><strong>Repositories &amp; Stores:</strong> WorkspaceRepository, AgencyRepository, AuditLogRepository</li><li><strong>Authentication:</strong> <code>Authorization: Bearer &lt;accessToken&gt;</code> verified by <code>JwtAuthFilterGatewayFilterFactory</code> (<code>brandhub-api-gateway</code>) and <code>JwtAuthenticationFilter</code> / <code>@RequireRoleAspect</code> (<code>brandhub-business-service</code>).</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Error Codes:</strong> <code>403 FORBIDDEN</code> (<code>BR-15</code>), <code>404 WORKSPACE_NOT_FOUND</code>, <code>400 WORKSPACE_NOT_DELETED</code>, <code>410 RESTORE_WINDOW_EXPIRED</code> (<code>BR-16</code>).</li><li><strong>Tenant Boundary Isolation:</strong> Soft-deleted Agencies/Workspaces (<code>EntityStatus.SOFT_DELETED</code>) and deactivated memberships (<code>is_active = false</code>) are excluded from operational reads and rejected on mutations.</li><li><strong>Concurrency &amp; Idempotency:</strong> Transactional persistence (<code>@Transactional</code>) and database unique constraints prevent duplicate memberships, duplicate active Managers, or partial writes under concurrent requests.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints and service logic verified against <a href="./test.html">test.md</a>, Web &amp; Mobile UI wired to live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark mode verified.</li><li><strong>Out of Scope:</strong> Adjacent Agency/Workspace operations covered by sibling FRs in <code>3.4.1–3.4.26</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA Agency &amp; Workspace Spec</a> · <a href="./../../../../ba/01-organization-structure.html">Organization Structure</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const h=t(s,[["render",c]]);export{u as __pageData,h as default};
